    "@types/node": "^22.5.0",
    "jest": "^29.7.0",
    "ts-jest": "^29.1.5",
    "typescript": "^5.5.4"
  }
}

export interface PageMeta {
  title: string;
  date?: string;
  tags: string[];
}

export interface ParsedMarkdown {
  meta: PageMeta;
  content: string;
  html: string;
}

export interface Post extends PageMeta {
  slug: string;
  content: string;
  html: string;
}

import matter from 'gray-matter';
import { marked } from 'marked';

import { PageMeta, ParsedMarkdown } from './types';

export function normalizeTags(tags: unknown): string[] {
  if (tags == null) {
    return [];
  }
  if (Array.isArray(tags)) {
    return tags.map((tag) => String(tag).trim()).filter((tag) => tag.length > 0);
  }
  if (typeof tags === 'string') {
    return tags
      .split(',')
      .map((tag) => tag.trim())
      .filter((tag) => tag.length > 0);
  }
  const value = String(tags).trim();
  return value ? [value] : [];
}

function normalizeDate(date: unknown): string | undefined {
  if (date instanceof Date) {
    return date.toISOString().slice(0, 10);
  }
  if (typeof date === 'string' && date.trim().length > 0) {
    return date.trim();
  }
  return undefined;
}

export function renderMarkdown(content: string): string {
  return marked.parse(content) as string;
}

/**
 * Parse a Markdown document with YAML frontmatter.
 *
 * gray-matter strips the `---` delimited frontmatter and returns the body in
 * `content`. We only ever pass that stripped body to `marked`, so the
 * frontmatter delimiter is never rendered as literal HTML.
 */
export function parseMarkdown(source: string): ParsedMarkdown {
  const { data, content } = matter(source);

  const meta: PageMeta = {
    title: typeof data.title === 'string' ? data.title : '',
    tags: normalizeTags(data.tags),
  };
  const date = normalizeDate(data.date);
  if (date) {
    meta.date = date;
  }

  const html = renderMarkdown(content);

  return { meta, content, html };
}

import fs from 'fs';
import path from 'path';

import { parseMarkdown } from './markdown';
import { Post } from './types';

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
}

export interface BuildResult {
  posts: Post[];
  filesWritten: string[];
  outputDir: string;
}

function escapeHtml(value: string): string {
  return String(value).replace(/[&<>"']/g, (ch) => {
    switch (ch) {
      case '&':
        return '&amp;';
      case '<':
        return '&lt;';
      case '>':
        return '&gt;';
      case '"':
        return '&quot;';
      case "'":
        return '&#39;';
      default:
        return ch;
    }
  });
}

function listMarkdownFiles(dir: string): string[] {
  const files: string[] = [];
  if (!fs.existsSync(dir)) {
    return files;
  }
  for (const entry of fs.readdirSync(dir)) {
    const fullPath = path.join(dir, entry);
    const stat = fs.statSync(fullPath);
    if (stat.isDirectory()) {
      files.push(...listMarkdownFiles(fullPath));
    } else if (stat.isFile() && /\.md$/i.test(entry)) {
      files.push(fullPath);
    }
  }
  return files;
}

function slugForFile(filePath: string, contentDir: string): string {
  const relative = path.relative(contentDir, filePath);
  const withoutExtension = relative.replace(/\.md$/i, '');
  return withoutExtension.split(path.sep).join('/');
}

function renderIndex(posts: Post[]): string {
  const items = posts
    .map((post) => {
      const href = `${post.slug}.html`;
      const title = escapeHtml(post.title || post.slug);
      const date = post.date
        ? `<time datetime="${escapeHtml(post.date)}">${escapeHtml(post.date)}</time>`
        : '';
      const tags = post.tags.length
        ? `<span class="tags">${post.tags.map(escapeHtml).join(', ')}</span>`
        : '';
      const meta = [date, tags].filter(Boolean).join(' ');
      return `<li><a href="${href}">${title}</a>${meta ? ` — ${meta}` : ''}</li>`;
    })
    .join('\n    ');

  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Site Index</title>
</head>
<body>
  <header><h1>Site Index</h1></header>
  <main>
    <ul>
    ${items || '<li>(no pages)</li>'}
    </ul>
  </main>
</body>
</html>
`;
}

function renderPage(post: Post): string {
  const title = escapeHtml(post.title || post.slug);
  const date = post.date
    ? `<time datetime="${escapeHtml(post.date)}">${escapeHtml(post.date)}</time>`
    : '';
  const tags = post.tags.length
    ? `<p class="tags">Tags: ${post.tags.map(escapeHtml).join(', ')}</p>`
    : '';

  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${title}</title>
</head>
<body>
  <header>
    <a href="index.html">← Index</a>
    <h1>${title}</h1>
    ${date ? `<p>${date}</p>` : ''}
    ${tags}
  </header>
  <main>
${post.html}
  </main>
</body>
</html>
`;
}

export function buildSite(options: BuildOptions): BuildResult {
  const { contentDir, outputDir } = options;
  const markdownFiles = listMarkdownFiles(contentDir);

  const posts: Post[] = markdownFiles.map((filePath) => {
    const source = fs.readFileSync(filePath, 'utf-8');
    const { meta, content, html } = parseMarkdown(source);
    return {
      slug: slugForFile(filePath, contentDir),
      title: meta.title || slugForFile(filePath, contentDir),
      date: meta.date,
      tags: meta.tags,
      content,
      html,
    };
  });

  posts.sort((a, b) => {
    const dateA = a.date ? Date.parse(a.date) : NaN;
    const dateB = b.date ? Date.parse(b.date) : NaN;
    if (!Number.isNaN(dateA) && !Number.isNaN(dateB) && dateA !== dateB) {
      return dateB - dateA;
    }
    if (Number.isNaN(dateA) && !Number.isNaN(dateB)) {
      return 1;
    }
    if (!Number.isNaN(dateA) && Number.isNaN(dateB)) {
      return -1;
    }
    return a.title.localeCompare(b.title);
  });

  fs.mkdirSync(outputDir, { recursive: true });

  const filesWritten: string[] = [];

  const indexPath = path.join(outputDir, 'index.html');
  fs.writeFileSync(indexPath, renderIndex(posts));
  filesWritten.push(indexPath);

  for (const post of posts) {
    const pagePath = path.join(outputDir, `${post.slug}.html`);
    fs.mkdirSync(path.dirname(pagePath), { recursive: true });
    fs.writeFileSync(pagePath, renderPage(post));
    filesWritten.push(pagePath);
  }

  return { posts, filesWritten, outputDir };
}

#!/usr/bin/env node
import { buildSite, BuildResult } from './site';

export interface CliOptions {
  command?: string;
  content?: string;
  output?: string;
}

export function parseArgs(argv: string[]): CliOptions {
  const args = argv.slice(2);
  const options: CliOptions = {};

  for (let i = 0; i < args.length; i += 1) {
    const arg = args[i];
    if (arg === '--content' || arg === '-c') {
      options.content = args[++i];
    } else if (arg === '--output' || arg === '-o') {
      options.output = args[++i];
    } else if (arg.startsWith('--content=')) {
      options.content = arg.slice('--content='.length);
    } else if (arg.startsWith('--output=')) {
      options.output = arg.slice('--output='.length);
    } else if (!arg.startsWith('-')) {
      options.command = arg;
    }
  }

  return options;
}

export function run(argv: string[]): BuildResult {
  const options = parseArgs(argv);
  if (options.command !== 'build') {
    throw new Error('Unknown command. Usage: ssg build [--content <dir>] [--output <dir>]');
  }
  return buildSite({
    contentDir: options.content || './content',
    outputDir: options.output || './dist',
  });
}

export function main(argv: string[] = process.argv): void {
  const options = parseArgs(argv);
  if (options.command !== 'build') {
    console.error('Usage: ssg build [--content <dir>] [--output <dir>]');
    process.exitCode = 1;
    return;
  }
  const result = buildSite({
    contentDir: options.content || './content',
    outputDir: options.output || './dist',
  });
  console.log(`Built ${result.posts.length} page(s) into ${options.output || './dist'}`);
}

if (require.main === module) {
  main();
}

export { buildSite } from './site';
export type { BuildOptions, BuildResult } from './site';
export { parseMarkdown, renderMarkdown, normalizeTags } from './markdown';
export type { PageMeta, ParsedMarkdown, Post } from './types';

import { parseMarkdown, renderMarkdown, normalizeTags } from '../src/markdown';

describe('parseMarkdown', () => {
  it('extracts title, date and tags from YAML frontmatter', () => {
    const source = `---
title: Hello World
date: 2024-01-15
tags:
  - typescript
  - ssg
---
# Body heading

Some **bold** content.
`;
    const result = parseMarkdown(source);

    expect(result.meta.title).toBe('Hello World');
    expect(result.meta.date).toBe('2024-01-15');
    expect(result.meta.tags).toEqual(['typescript', 'ssg']);
  });

  it('strips frontmatter so the `---` delimiter is never rendered as HTML', () => {
    const source = `---
title: No Delimiters
tags: [a, b]
---
# Heading
`;
    const result = parseMarkdown(source);

    expect(result.content).not.toContain('---');
    expect(result.html).not.toContain('---');
    expect(result.html).toContain('<h1');
  });

  it('returns empty metadata and the full body when there is no frontmatter', () => {
    const source = '# Just a heading\n';
    const result = parseMarkdown(source);

    expect(result.meta.title).toBe('');
    expect(result.meta.tags).toEqual([]);
    expect(result.meta.date).toBeUndefined();
    expect(result.html).toContain('<h1>Just a heading</h1>');
  });

  it('normalizes comma-separated string tags into an array', () => {
    const source = `---
title: Tags
tags: one, two, three
---
Body
`;
    const result = parseMarkdown(source);
    expect(result.meta.tags).toEqual(['one', 'two', 'three']);
  });
});

describe('renderMarkdown', () => {
  it('converts markdown to HTML', () => {
    const html = renderMarkdown('# Title\n\n- item one\n- item two');
    expect(html).toContain('<h1>Title</h1>');
    expect(html).toContain('<li>item one</li>');
  });
});

describe('normalizeTags', () => {
  it('handles array, string and missing values', () => {
    expect(normalizeTags(['a', 'b'])).toEqual(['a', 'b']);
    expect(normalizeTags('a, b')).toEqual(['a', 'b']);
    expect(normalizeTags(undefined)).toEqual([]);
    expect(normalizeTags(null)).toEqual([]);
  });
});

import fs from 'fs';
import os from 'os';
import path from 'path';

import { buildSite } from '../src/site';

function makeTempContentDir(): string {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-content-'));
  return dir;
}

function writeFixture(contentDir: string): void {
  fs.writeFileSync(
    path.join(contentDir, 'hello.md'),
    `---
title: Hello World
date: 2024-01-15
tags:
  - intro
---
# Welcome

This is the **first** post.
`
  );
  fs.writeFileSync(
    path.join(contentDir, 'about.md'),
    `---
title: About
date: 2024-03-02
tags: [meta]
---
# About Us

We build things.
`
  );
  fs.writeFileSync(
    path.join(contentDir, 'nested', 'deep.md'),
    `---
title: Deep Page
---
Nested content.
`
  );
}

describe('buildSite', () => {
  let contentDir: string;
  let outputDir: string;

  beforeEach(() => {
    contentDir = makeTempContentDir();
    outputDir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-dist-'));
    writeFixture(contentDir);
  });

  afterEach(() => {
    fs.rmSync(contentDir, { recursive: true, force: true });
    fs.rmSync(outputDir, { recursive: true, force: true });
  });

  it('generates an index.html and one HTML file per page', () => {
    const result = buildSite({ contentDir, outputDir });

    expect(result.posts).toHaveLength(3);
    expect(fs.existsSync(path.join(outputDir, 'index.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'hello.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'about.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'nested', 'deep.html'))).toBe(true);
    expect(result.filesWritten).toHaveLength(4);
  });

  it('lists every page in the index with a title and link', () => {
    buildSite({ contentDir, outputDir });

    const index = fs.readFileSync(path.join(outputDir, 'index.html'), 'utf-8');
    expect(index).toContain('Hello World');
    expect(index).toContain('About');
    expect(index).toContain('Deep Page');
    expect(index).toContain('href="hello.html"');
    expect(index).toContain('href="about.html"');
    expect(index).toContain('href="nested/deep.html"');
  });

  it('orders pages by date, newest first', () => {
    const result = buildSite({ contentDir, outputDir });

    const slugs = result.posts.map((post) => post.slug);
    expect(slugs.indexOf('about')).toBeLessThan(slugs.indexOf('hello'));
  });

  it('renders markdown content into each page without frontmatter delimiters', () => {
    buildSite({ contentDir, outputDir });

    const page = fs.readFileSync(path.join(outputDir, 'hello.html'), 'utf-8');
    expect(page).toContain('<h1>Welcome</h1>');
    expect(page).toContain('<strong>first</strong>');
    expect(page).not.toContain('---');
  });

  it('honours a custom output directory', () => {
    const custom = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-custom-'));
    try {
      buildSite({ contentDir, outputDir: custom });
      expect(fs.existsSync(path.join(custom, 'index.html'))).toBe(true);
      expect(fs.existsSync(path.join(custom, 'hello.html'))).toBe(true);
    } finally {
      fs.rmSync(custom, { recursive: true, force: true });
    }
  });

  it('produces an empty index for a missing content directory', () => {
    const result = buildSite({
      contentDir: path.join(contentDir, 'does-not-exist'),
      outputDir,
    });

    expect(result.posts).toHaveLength(0);
    const index = fs.readFileSync(path.join(outputDir, 'index.html'), 'utf-8');
    expect(index).toContain('(no pages)');
  });
});

import { parseArgs } from '../src/cli';

describe('parseArgs', () => {
  it('parses the build command with defaults', () => {
    expect(parseArgs(['node', 'cli.js', 'build'])).toEqual({ command: 'build' });
  });

  it('parses --content and --output options', () => {
    expect(parseArgs(['node', 'cli.js', 'build', '--content', 'src/pages', '--output', 'public'])).toEqual({
      command: 'build',
      content: 'src/pages',
      output: 'public',
    });
  });

  it('parses --content= and --output= options', () => {
    expect(parseArgs(['node', 'cli.js', 'build', '--content=content', '--output=dist'])).toEqual({
      command: 'build',
      content: 'content',
      output: 'dist',
    });
  });

  it('parses short flags', () => {
    expect(parseArgs(['node', 'cli.js', 'build', '-c', 'c', '-o', 'o'])).toEqual({
      command: 'build',
      content: 'c',
      output: 'o',
    });
  });
});
